contracts.definition:
const send = (msg: ServerMessage) => {
  const sid = (msg.payload as { sessionId?: string } | null)?.sessionId
  if (sid) this.messageBus?.publish(sid, msg)  // session 级走 bus（双写）
  this.broker.broadcast(msg)  // 保留盲广播（过渡兼容）
  if (msg.type === 'message.complete' && sid) this.onMessageComplete?.(sid)
}

case 'session.subscribe': {
  const { sessionId, fromSeq } = msg.payload
  const result = ctx.messageBus.subscribe(sessionId, ws as unknown as BusClient)
  let gap = false
  let snapshot = result.snapshot
  if (fromSeq !== undefined) {
    const oldestSeq = snapshot[0]?.seq ?? 0
    if (fromSeq < oldestSeq) gap = true
    else snapshot = snapshot.filter(m => (m.seq ?? 0) > fromSeq)
  }
  ctx.reply(ws, msg.id, 'session.subscribe', { snapshot, lastSeq: result.lastSeq, gap })
  return
}

case 'session.unsubscribe': {
  const { sessionId } = msg.payload
  ctx.messageBus.unsubscribe(sessionId, ws as unknown as BusClient)
  ctx.reply(ws, msg.id, 'session.unsubscribe', undefined)
  return
}
